package com.portfolio.agent.infrastructure.model.policy;
import org.junit.jupiter.api.Test; import java.util.Map; import static org.assertj.core.api.Assertions.*;
class ModelOperationPolicyTest { @Test void allOperationsDefaultDisabled(){assertThat(ModelOperationPolicyRegistry.defaults().asMap()).allSatisfy((op,p)->assertThat(p.getMode()).isEqualTo(OperationMode.DISABLED));} @Test void enabledIncompleteOperationFailsStartup(){assertThatThrownBy(()->new ModelOperationPolicyRegistry(Map.of(ModelOperation.GENERAL_KNOWLEDGE,new ModelOperationPolicy(ModelOperation.GENERAL_KNOWLEDGE,OperationMode.ENABLED,"provider",null)))).isInstanceOf(IllegalStateException.class);} @Test void operationsAreIndependent(){ModelOperationPolicy p=new ModelOperationPolicy(ModelOperation.GENERAL_KNOWLEDGE,OperationMode.ENABLED,"provider","schema-v1");assertThat(p.readiness()).isEqualTo(OperationReadiness.AVAILABLE_WITH_DETERMINISTIC_FALLBACK);assertThat(ModelOperationPolicyRegistry.defaults().get(ModelOperation.TURN_INTERPRETATION).getMode()).isEqualTo(OperationMode.DISABLED);} }
